window.blogDetail = {"blogId":1398945398,"blogType":3,"pubTime":"2014-05-01 19:56","cate":"作文选揖","cateHex":"d7f7cec4d1a1d2be","title":"青青四月下扬州","commentNum":0,"effect1":8389120,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"青青四月下扬州<br/>又一次，我满怀深情地提起笔来书写我心中的一幅淡雅优美的山水画。好久没写了，不知自己能否将自己心中的美景有文字一点点的编织出来，永远保留在纸上，夹在记忆的书签里，以供闲时翻阅。<br/>“故人西辞黄鹤楼，烟花三月下扬州”很早的时候就会背诵这首诗，对着书，我常常遐想，扬州究竟是个什么好地方，能让李白的友情顺着悠悠的长江水一直流淌千年，流进了千家万户，流进了每个学生的心中？就这样...","artype":1,"arUins":"","blogid":1398945398,"voteids":0,"pubtime":1398945398,"replynum":0,"category":"作文选揖","effect":8389120,"exblogtype":3,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":81177,"lp_style":16843520,"lp_flag":0,"lp_topvalue":0,"orguin":619774944,"orgblogid":1398945398,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"青青四月下扬州","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1398945398"}